use std::fs

trait Shape {
    fn name(self) -> string
    fn corners(self) -> int
    fn double_area(self) -> int
}

struct Square { s: int }
struct Rect { w: int, h: int }
struct RTri { a: int, b: int }
struct Trap { a: int, b: int, h: int }

impl Shape for Square {
    fn name(self) -> string { "square" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.s * self.s }
}
impl Shape for Rect {
    fn name(self) -> string { "rect" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.w * self.h }
}
impl Shape for RTri {
    fn name(self) -> string { "rtri" }
    fn corners(self) -> int { 3 }
    fn double_area(self) -> int { self.a * self.b }
}
impl Shape for Trap {
    fn name(self) -> string { "trap" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { (self.a + self.b) * self.h }
}

fn show(s: Box<dyn Shape>) -> int {
    let d = s.double_area()
    println("${s.name()} corners=${s.corners()} area2=${d}")
    d
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut total = 0
    let mut best = -1
    let mut best_name = "none"
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().collect()
        if p.len() == 0 { continue }
        let k = p[0]
        let mut d = 0
        if k == "square" {
            d = show(Box::new(Square { s: p[1].parse::<int>().unwrap_or(0) }))
        } else if k == "rect" {
            d = show(Box::new(Rect { w: p[1].parse::<int>().unwrap_or(0), h: p[2].parse::<int>().unwrap_or(0) }))
        } else if k == "rtri" {
            d = show(Box::new(RTri { a: p[1].parse::<int>().unwrap_or(0), b: p[2].parse::<int>().unwrap_or(0) }))
        } else if k == "trap" {
            d = show(Box::new(Trap { a: p[1].parse::<int>().unwrap_or(0), b: p[2].parse::<int>().unwrap_or(0), h: p[3].parse::<int>().unwrap_or(0) }))
        } else {
            continue
        }
        total += d
        if d > best {
            best = d
            best_name = k
        }
    }
    println("total area2=${total}")
    if best < 0 {
        println("largest=none")
    } else {
        println("largest=${best_name} area2=${best}")
    }
}

